const lessons=[{"sentences":[{"speaker":"A","text":"Attention all staff members because we need extra help preparing the main conference hall for tomorrow morning.","position":1,"audioStartSeconds":0,"audioEndSeconds":6.6545},{"speaker":"A","text":"The marketing team requested additional chairs although our inventory manager already placed twenty seats near the podium.","position":2,"audioStartSeconds":6.8545,"audioEndSeconds":14.136166666666666},{"speaker":"A","text":"If you finish your current administrative reports before noon please report directly to room four hundred.","position":3,"audioStartSeconds":14.336166666666667,"audioEndSeconds":20.624833333333335},{"speaker":"A","text":"Our maintenance supervisor will distribute extra clipboards and pens when volunteers arrive at the designated area.","position":4,"audioStartSeconds":20.824833333333334,"audioEndSeconds":27.706291666666665},{"speaker":"A","text":"Please remember to wear your employee identification badges so security guards can grant you proper access.","position":5,"audioStartSeconds":27.906291666666668,"audioEndSeconds":34.67175},{"speaker":"A","text":"We appreciate your dedication whenever unexpected tasks disrupt your normal daily schedules.","position":6,"audioStartSeconds":34.87175,"audioEndSeconds":40.954208333333334},{"speaker":"A","text":"Please listen carefully if you are scheduled to attend the regional sales presentation this coming Thursday.","role":"section-start","position":7,"audioStartSeconds":45.954208333333334,"audioEndSeconds":52.16558333333333},{"speaker":"A","text":"Management decided to postpone the morning session because the keynote speaker experienced unexpected travel delays overseas.","position":8,"audioStartSeconds":52.36558333333333,"audioEndSeconds":60.26504166666667},{"speaker":"A","text":"The revised keynote address will begin at two in the afternoon instead of the original ten o'clock time.","position":9,"audioStartSeconds":60.465041666666664,"audioEndSeconds":66.83104166666666},{"speaker":"A","text":"Lunch will still be served in the cafeteria at twelve because catering arrangements cannot be changed.","position":10,"audioStartSeconds":67.03104166666667,"audioEndSeconds":73.34545833333334},{"speaker":"A","text":"If you registered online you should check your email for updated calendar invitations and parking instructions.","position":11,"audioStartSeconds":73.54545833333333,"audioEndSeconds":80.46554166666667},{"speaker":"A","text":"We apologize for any inconvenience caused when schedules change at such a late date.","position":12,"audioStartSeconds":80.66554166666667,"audioEndSeconds":86.24141666666667}],"questions":[{"prompt":"What is the primary purpose of the first announcement?","options":["To request volunteers for room setup.","To announce a new marketing strategy.","To report a broken inventory system."],"answer":"A","evidenceSentence":1,"evidence":"preparing the main conference hall","explanation":"Thông báo mở đầu bằng việc kêu gọi sự giúp đỡ để chuẩn bị phòng hội nghị chính cho buổi sáng mai."},{"prompt":"Where should staff members go after finishing their reports?","options":["To the cafeteria.","To room four hundred.","To the security office."],"answer":"B","evidenceSentence":3,"evidence":"report directly to room four hundred","explanation":"Người nói hướng dẫn nhân viên đến phòng bốn trăm nếu họ hoàn thành báo cáo trước buổi trưa."},{"prompt":"What item must employees wear to gain access?","options":["A visitor lanyard.","An identification badge.","A maintenance uniform."],"answer":"B","evidenceSentence":5,"evidence":"employee identification badges","explanation":"Nhân viên phải đeo thẻ nhận dạng nhân viên để nhân viên bảo vệ cho phép ra vào."},{"prompt":"Why was the morning session postponed in the second announcement?","options":["The speaker faced travel delays.","The catering company cancelled lunch.","The conference room was unavailable."],"answer":"A","evidenceSentence":8,"evidence":"keynote speaker experienced unexpected travel delays","explanation":"Phiên buổi sáng bị hoãn vì diễn giả chính gặp sự cố chậm trễ khi đi lại."},{"prompt":"What time will the revised keynote address begin?","options":["At ten in the morning.","At twelve in the afternoon.","At two in the afternoon."],"answer":"C","evidenceSentence":9,"evidence":"begin at two in the afternoon","explanation":"Bài phát biểu chính đã sửa đổi sẽ bắt đầu lúc hai giờ chiều thay vì mười giờ sáng."},{"prompt":"What should registered attendees check for updated details?","options":["Their postal mail.","Their email inbox.","The office bulletin board."],"answer":"B","evidenceSentence":11,"evidence":"check your email for updated","explanation":"Những người đã đăng ký trực tuyến nên kiểm tra email để nhận lời mời lịch mới."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
